55	/**
56	 * Why this project's `merge.governed_paths` cannot be honoured as written.
57	 *
58	 * The same check `merge.gates` patterns get, on the gate that matters more.
59	 * `merge.governed_paths` decides which changes to the agent's own limits fall to a
60	 * person, so a pattern that matches nothing hands the agent exactly what the
61	 * setting was written to withhold — and does it in silence.
62	 *
63	 * Reported through the same `gate-config-invalid` blocker as a bad `merge.gates`
64	 * entry, because it is the same sentence to the person reading it: a gate this
65	 * project declared could not be evaluated, so the merge is theirs.
66	 */
67	function governedPathProblems(): string[] {
68	  return getGovernedPaths()
69	    .map((pattern) => pathPatternProblem(pattern))
70	    .filter((problem) => problem !== "")
71	    .map((problem) => `\`merge.governed_paths\`: ${problem}`);
72	}
