74	/**
75	 * GitHub's per-file statuses, reduced to the three a gate can name.
76	 *
77	 * `copied` is an addition. `renamed` is an addition at the new path, and the
78	 * removal at the old one is added separately below. `changed` is GitHub's word
79	 * for a mode or type change, which is a modification.
80	 */
81	const STATUS_MAP: Record<string, FileStatus> = {
82	  added: "added",
83	  copied: "added",
84	  renamed: "added",
85	  removed: "removed",
86	  modified: "modified",
87	  changed: "modified",
88	};
89	
90	/**
91	 * Statuses that are not a change at all.
92	 *
93	 * `unchanged` appears when GitHub lists a file whose content is identical to the
94	 * base. Mapping it to `modified` would fire a gate over a file nobody touched.
95	 */
96	const NOT_A_CHANGE = new Set(["unchanged"]);
97	
98	interface ChangedFilesRead {
99	  readonly files: readonly ChangedFile[];
100	  /** Why the read cannot be trusted, or "" when it can. */
101	  readonly problem: string;
102	}
103	
104	/**
105	 * What this pull request changes, and what happened to each file.
106	 *
107	 * Fails CLOSED, unlike `readBranchRules` in `branch-rules.ts`, and the two differ because of
108	 * what each failure costs. An unreadable rule list only makes a refusal less
109	 * specific; an unreadable file list, treated as empty, would let an agent merge
110	 * exactly the change the governance gate and every declared merge gate exist to
111	 * stop. So a failure here comes back as a problem, and a problem blocks.
112	 *
113	 * One read serves both gates. They ask different questions of the same list, and
114	 * two calls would be two chances for one of them to silently see nothing.
115	 */
116	function readChangedFiles(repo: string, num: number): ChangedFilesRead {
117	  // `--jq` rather than parsing the response: with `--paginate` the pages arrive
118	  // as separate JSON documents, which `JSON.parse` cannot read, and dropping
119	  // `--paginate` would silently stop at 100 files — a large pull request could
120	  // then hide a workflow change on page two.
121	  //
122	  // One JSON array per line rather than `@tsv`, because a tracked path may
123	  // legitimately contain a tab or a newline and `@tsv` renders both as escapes
124	  // that split into the wrong fields — a file whose name held a tab would arrive
125	  // as a status with no path, which `readChangedFiles` reports as unrecognised
126	  // and turns into a blocker on an honest pull request.
127	  //
128	  // `@json` escapes them inside the string, so one file stays one line and
129	  // `JSON.parse` gives the exact bytes back. `previous_filename` is absent on all
130	  // but a rename, hence the `//` default.
131	  // Not `pull-request.ts`'s read, and the reason is the question: the list of files a
132	  // pull request changes is a paginated sub-resource (`pulls/<n>/files`), not a field of
133	  // the request, so it has its own endpoint, its own page loop, and its own failure
134	  // policy — this one fails CLOSED, where every projection of the request itself degrades.
135	  //
136	  // `ghRead`, like the pull-request reads in `gatherMergeSignals`: a transient failure
137	  // here is not an answer either. It comes back as `problem`, and a problem blocks the
138	  // merge — so on plain `gh` one `HTTP 504` refused a merge that was fine, which is the
139	  // same false refusal the retry on `mergeStateStatus` exists to prevent.
140	  const { code, stdout } = ghRead(
141	    "api",
142	    `repos/${repo}/pulls/${num}/files?per_page=100`,
143	    "--paginate",
144	    "--jq",
145	    '.[] | [.status, .filename, (.previous_filename // "")] | @json',
146	  );
147	  if (code) {
148	    log(`WARN could not read changed files for #${num}; treating the merge as a person's`);
149	    return { files: [], problem: `the changed files of #${num} could not be read` };
150	  }
151	
152	  const files: ChangedFile[] = [];
153	  for (const line of stdout.split("\n")) {
154	    if (line.trim() === "") continue;
155	    let status = "";
156	    let path = "";
157	    let previous = "";
158	    try {
159	      [status, path, previous] = JSON.parse(line) as [string, string, string];
160	    } catch {
161	      // Fail closed, like every other unreadable answer here. A line this cannot
162	      // parse means the list is not the list, and guessing at the rest of it
163	      // would be guessing at which files a gate should have seen.
164	      return { files: [], problem: `the changed-file list of #${num} could not be parsed` };
165	    }
166	    if (NOT_A_CHANGE.has((status ?? "").trim())) continue;
167	    const mapped = STATUS_MAP[(status ?? "").trim()];
168	    if (!mapped || !path) {
169	      // Not a case to guess at. Treating an unrecognised status as "modified"
