173	 * `governance-unknown` and `blocked` all stop the agent from merging and leave
174	 * the head commit exactly as it is -- so the check is still needed, and still
175	 * worth writing, by whoever ends up merging. The kinds below are the ones where
176	 * it is not: the commit must change first, or there is nothing to validate.
177	 *
178	 * `checks-pending` and `checks-failing` are here for the other reason: a run
179	 * already exists for this commit, so starting a second one duplicates it.
180	 */
181	const CI_WOULD_BE_WASTED: ReadonlySet<BlockerKind> = new Set([
182	  "not-open",
183	  "draft",
184	  "conflicting",
185	  "behind",
186	  "mergeability-unknown",
187	  "checks-pending",
188	  "checks-failing",
189	]);
