191	export interface MergeReadiness {
192	  ready: boolean;
193	  blockers: Blocker[];
194	  /** True when a required check has never run on the head commit. */
195	  needsCiDispatch: boolean;
196	}
197	
198	/** Conclusions that satisfy a required check. Skipped and neutral are not failures. */
199	const PASSING = new Set(["success", "neutral", "skipped"]);
200	
201	/**
202	 * The deployed files that decide how an agent runs, and so what it may reach.
203	 *
204	 * Deployed paths, not source paths: this is what an adopter's repository looks
205	 * like. A template repository developing the same files under `src/` is doing
206	 * ordinary work on ordinary files, and adds its own patterns if it wants them
207	 * covered.
208	 *
209	 * One pattern rather than a list of the directories that matter, because the
210	 * list was wrong. It named `workflows`, `actions`, `atoma` and `rulesets` and
211	 * omitted `.github/scripts/**` — where the runner's own control logic lives, run
212	 * by a job holding `contents: write`, `issues: write`, `pull-requests: write`
213	 * and `actions: write`. An agent could rewrite the rule releasing the
214	 * in-progress guard, or the auto-dispatch loop limit, and merge it unreviewed.
215	 *
216	 * Nothing chose that; enumerating did. `.github/scripts/` arrived after the list
217	 * was written and nobody added it. A list of exceptions has to be revisited every
218	 * time the tree grows, and it silently fails when it is not — so this covers the
219	 * directory and lets a project narrow it, rather than naming parts and hoping the
220	 * next addition is noticed.
221	 *
222	 * It reaches a few files that are not an agent's limits — `dependabot.yml`,
223	 * `CODEOWNERS`, issue templates. Those change rarely, and the first two are
224	 * things a person should see change anyway.
225	 */
226	export const DEFAULT_GOVERNED_PATHS = [".github/**"] as const;
227	
228	/** A file whose changer probably meant to change what CI or a deployment does. */
229	function isGeneratedWorkflow(path: string): boolean {
230	  return path.startsWith(".github/workflows/");
231	}
232	
233	/**
234	 * Which of `files` a pattern claims.
235	 *
236	 * The matcher itself moved to `path-patterns.ts`, which explains the one pattern
237	 * form Atomaton accepts and why. `merge.gates` needed the same comparison, and two
238	 * copies of a security-shaped one is the arrangement that drifts.
239	 */
240	export function governedPathsIn(files: string[], patterns: readonly string[]): string[] {
241	  return files.filter((file) => patterns.some((pattern) => pathMatches(file, pattern)));
242	}
243	
244	/**
245	 * Explain a BLOCKED verdict in terms of the required checks, so a refusal names
246	 * the check to fix rather than restating that GitHub said no.
247	 */
248	function explainRequiredChecks(signals: MergeSignals): Blocker[] {
249	  const blockers: Blocker[] = [];
250	  const byName = new Map(signals.checks.map((c) => [c.name, c]));
251	
252	  for (const context of signals.requiredChecks) {
253	    const run = byName.get(context);
254	    if (!run) {
255	      blockers.push({
256	        kind: "checks-missing",
257	        detail: `required check "${context}" has not run on the head commit`,
258	      });
259	    } else if (run.status !== "completed") {
260	      blockers.push({
261	        kind: "checks-pending",
262	        detail: `required check "${context}" is ${run.status}`,
263	      });
264	    } else if (!PASSING.has((run.conclusion ?? "").toLowerCase())) {
265	      const where = run.detailsUrl ? ` (${run.detailsUrl})` : "";
266	      blockers.push({
267	        kind: "checks-failing",
268	        detail: `required check "${context}" concluded ${run.conclusion}${where}`,
269	      });
270	    }
271	  }
272	  return blockers;
273	}
