275	export function decideMergeReadiness(signals: MergeSignals): MergeReadiness {
276	  const blockers: Blocker[] = [];
277	
278	  if (signals.state?.toUpperCase() !== "OPEN") {
279	    blockers.push({ kind: "not-open", detail: `pull request state is ${signals.state}, not OPEN` });
280	  }
281	
282	  // Before the verdict, because the verdict does not carry this. GitHub reports
283	  // `CLEAN` for a draft, so relying on the `DRAFT` case below reported a draft as
284	  // ready and left the refusal to come back from the merge call as a raw API error
285	  // no blocker kind described.
286	  if (signals.isDraft) {
287	    blockers.push({ kind: "draft", detail: "pull request is a draft; mark it ready for review first" });
288	  }
289	
290	  switch (signals.mergeStateStatus?.toUpperCase()) {
291	    case "CLEAN":
292	      break;
293	    case "UNSTABLE":
294	      // A check is failing and no rule requires it. On a repository that HAS rules
295	      // that is a decision -- somebody chose not to require this one -- and merging is
296	      // allowed. Where rules cannot exist, nobody decided anything: it is just a red
297	      // build with nothing standing in front of it, and letting an agent merge that
298	      // would make "we handle the free private case" mean "we quietly stopped
299	      // checking". Atomaton refuses in GitHub's place.
300	      if (!signals.requiredChecksEnforceable) {
301	        for (const run of signals.checks) {
302	          if (run.status !== "completed") continue;
303	          if (PASSING.has((run.conclusion ?? "").toLowerCase())) continue;
304	          const where = run.detailsUrl ? ` (${run.detailsUrl})` : "";
305	          blockers.push({
306	            kind: "checks-failing",
307	            detail:
308	              `check "${run.name}" concluded ${run.conclusion}${where}. ` +
309	              "Branch rules are unavailable on this repository, so GitHub does not " +
310	              "block this merge and Atomaton does.",
311	          });
312	        }
313	      }
314	      break;
315	    case "DRAFT":
316	      // Kept although `isDraft` above already covers it, so this does not break if
317	      // GitHub starts returning the value its own docs list. Guarded to avoid
318	      // reporting the same blocker twice when it does.
319	      if (!signals.isDraft) {
320	        blockers.push({ kind: "draft", detail: "pull request is a draft; mark it ready for review first" });
321	      }
322	      break;
323	    case "DIRTY":
324	      blockers.push({
325	        kind: "conflicting",
326	        detail:
327	          "branch conflicts with the base; call merge_base_into_branch, resolve the conflicts it leaves, " +
328	          "then commit_and_push before merging",
329	      });
330	      break;
331	    case "BEHIND":
332	      blockers.push({
333	        kind: "behind",
334	        detail:
335	          "branch is behind the base and the ruleset requires it current; call merge_base_into_branch " +
336	          "(sync_branch only fast-forwards this branch from its own remote branch)",
337	      });
338	      break;
339	    case "BLOCKED": {
340	      // Blocked by branch protection. Name the specific required checks when we
341	      // can; fall back to the raw verdict when the cause is something else the
342	      // ruleset requires (a review, an unresolved thread).
343	      const explained = explainRequiredChecks(signals);

