371	  if (signals.mergePolicy !== "auto") {
372	    blockers.push({
373	      kind: "merge-policy",
374	      detail: `merge.policy is '${signals.mergePolicy}', not 'auto'; a human performs the merge`,
375	    });
376	  }
377	
378	  // Every other gate here is something an agent may satisfy and then merge. This
379	  // one it may not, because the change would alter the gates themselves.
380	  //
381	  // Workflows, agent definitions, tool configuration and rulesets are where an
382	  // agent's limits live — which credentials reach a run, which commands a hook
383	  // refuses, what a ruleset requires before a merge. An agent that can merge a
384	  // change to those can widen its own reach, and no later check catches it: the
385	  // next run already obeys the new file.
386	  //
387	  // Not a suspicion that an agent means to. A prompt injection carried in an
388	  // issue body, or a plain mistake, reaches just as far, and both stop at a
389	  // person reading the diff.
390	  // Same fail-closed outcome as the gate below, with a true sentence. The
391	  // changed files are what decides whether this touches governance, so not
392	  // having them means the question is open, and an open question about the
393	  // machinery agents run on is a person's to close.
394	  if (signals.governanceUnknown) {
395	    blockers.push({
396	      kind: "governance-unknown",
397	      detail:
398	        "whether this pull request changes how agents themselves run could not be determined " +
399	        `(${signals.governanceUnknown}), so the merge falls to a person`,
400	    });
401	  }
402	
403	  if (signals.governancePaths.length > 0) {
404	    const shown = signals.governancePaths.slice(0, 5).join(", ");
405	    const rest = signals.governancePaths.length - 5;
406	    blockers.push({
407	      kind: "governance-change",
408	      detail:
409	        `this pull request changes how agents themselves run (${shown}${rest > 0 ? `, +${rest} more` : ""}); ` +
410	        "review it and report, but leave the merge to a person" +
411	        // Said here because this is the moment someone is looking. The commonest
412	        // reason to touch a generated workflow is to change what CI or a
413	        // deployment does, and under Atomaton that is not where those live -- so
414	        // name the place it does live rather than only refusing the merge.
415	        (signals.governancePaths.some(isGeneratedWorkflow)
416	          ? ". If the intent was to change what CI or deployment does, that belongs in " +
417	            "`.github/atomaton/config.yaml` (`checks.from_pull_request`, `deploy.on_merge`) rather than in a " +
418	            "workflow file — an agent can write config and cannot write a workflow. If this is an " +
419	            "upgrade of the generated deliverable, it is exactly what a person should be merging"
420	          : ""),
421	    });
422	  }
423	
424	  // The project's own version of the gate above. Same shape, same outcome — the
425	  // agent reviews and reports, a person merges — but the condition comes from
426	  // `merge.gates` in config.yaml rather than from this file, because what must
427	  // not be merged unread is a property of the project and not of Atomaton. A
428	  // migration, a change to a pricing table, a release note: nothing here could
429	  // have guessed them.
430	  //
431	  // The reason is relayed verbatim, in whatever language it was written in. It is
432	  // addressed to the person who will merge, and they wrote it.
433	  for (const match of signals.gateMatches) {
434	    const shown = match.evidence.slice(0, 5).join(", ");
435	    const rest = match.evidence.length - 5;
436	    const because = shown ? ` (matched ${shown}${rest > 0 ? `, +${rest} more` : ""})` : "";
437	    blockers.push({
438	      kind: "merge-gate",
439	      detail:
440	        `a merge gate declared by this project applies${because}: ${match.reason}` +
441	        " — review it and report, but leave the merge to a person",
442	    });
443	  }
444	
445	  // Fail closed. An unreadable gate is the case this whole mechanism exists for:
446	  // if a broken declaration merely disappeared, the way to merge past a gate
447	  // would be to break it, and the diff that breaks it would be merged by the
448	  // agent the gate was meant to stop.
449	  for (const problem of signals.gateProblems) {
450	    blockers.push({
451	      kind: "gate-config-invalid",
452	      detail:
453	        `a declared merge gate could not be evaluated, so this merge falls to a person: ${problem}`,
454	    });
455	  }
456	
457	  const needsCiDispatch =
458	    blockers.some((b) => b.kind === "checks-missing") && !blockers.some((b) => CI_WOULD_BE_WASTED.has(b.kind));
459	
460	  return { ready: blockers.length === 0, blockers, needsCiDispatch };
461	}
