463	/** Render blockers as a numbered list for a tool result or an issue comment. */
464	export function formatBlockers(blockers: Blocker[]): string {
465	  return blockers.map((b, i) => `${i + 1}. [${b.kind}] ${b.detail}`).join("\n");
466	}

