4	 *
5	 * `atomaton/issue-<n>`, and `atomaton/issue-<n>-<k>` for the second and later. That
6	 * is a convention: it says which issue a branch belongs to by putting the number in
7	 * the name, because git has nowhere else to put it. Which branch to resume, and
8	 * whether a new one is needed at all, are work rules and live in
9	 * `domain/work/issue-branch.ts`.
10	 *
11	 * The two were one module, and the convention was written out in four places: twice
12	 * in the rule, once as `BRANCH_PREFIX` beside the placement logic, and once inside
13	 * a `matching-refs` path. Nothing had gone wrong with that yet, which is the usual
14	 * state of a literal repeated four times.
15	 */
16	
17	/** What every work branch starts with. The issue number follows it. */
18	export const BRANCH_PREFIX = "atomaton/issue-";
19	
20	/**
21	 * What may follow `atomaton/issue-<n>` in a branch that issue owns.
22	 *
23	 * Anchored at both ends, which is the whole point. Unanchored, the remainder of
24	 * `atomaton/issue-12-3` after the prefix for issue **1** is `2-3`, and a pattern
25	 * looking only for a trailing `-<digits>` finds one — so a run on issue 1 would
26	 * resume issue 12's branch, commit to it, and open a pull request from it.
27	 *
28	 * The check used to live in two places, the filter and the ordinal, each unanchored
29	 * in the same way. One arbiter: an ordinal of 0 means the branch is not this
30	 * issue's, and nothing else decides ownership.
31	 */
32	const OWNED_SUFFIX = /^-(\d+)$/;
33	
34	/** The branch for issue `issue`, at `ordinal`. The first has no suffix. */
35	export function branchNameFor(issue: number, ordinal: number): string {
36	  const base = `${BRANCH_PREFIX}${issue}`;
37	  return ordinal <= 1 ? base : `${base}-${ordinal}`;
38	}
39	
40	/** A parent issue's first branch name. */
41	export function branchOfIssue(issue: number): string {
42	  return branchNameFor(issue, 1);
43	}
44	
45	/** Whether a branch name is one of Atomaton's work branches, whichever issue it belongs to. */
46	export function isIssueBranch(name: string): boolean {
47	  return name.startsWith(BRANCH_PREFIX);
48	}
49	
50	/**
51	 * Which of `issue`'s branches this is: 1 for the first, 2 for `-2`, and 0 for a
52	 * name this issue does not own.
53	 */
54	export function ordinalOfBranch(name: string, issue: number): number {
55	  const base = `${BRANCH_PREFIX}${issue}`;
56	  if (!name.startsWith(base)) return 0;
57	  const rest = name.slice(base.length);
58	  if (rest === "") return 1;
59	  const match = OWNED_SUFFIX.exec(rest);
60	  return match ? Number(match[1]) : 0;
61	}
